export const BODY: string = "\n<p>تصویر کو 200KB تک کمپریس کرنے میں تقریباً دو منٹ لگتے ہیں۔ طریقہ سادہ ہے، مگر راستے میں چند فیصلے طے کرتے ہیں کہ نتیجہ شاندار لگے گا یا صرف قابل قبول۔</p>\n<p>یہ رہنما ہر مرحلہ بتاتا ہے۔ آپ ماخذ فائل تیار کریں گے، درست فارمیٹ چنیں گے، کمپریشن چلائیں گے اور استعمال سے پہلے نتیجہ کی تصدیق کریں گے۔</p>\n<p>یہ بلاگ تصویروں، مصنوعات کی تصاویر، پورٹ فولیو شاٹ اور فارم اپ لوڈ کے لیے کام کرتا ہے، لیپ ٹاپ پر بھی اور فون پر بھی۔</p>\n<h2 id=\"what-you-need\">شروع کرنے سے پہلے کیا چاہیے</h2>\n<p>آپ کو دستیاب بہترین کوالٹی میں اصل تصویر چاہیے۔ کیمرے کی تصویر مثالی ہے، چیٹ ایپ سے آگے بھیجی گئی کاپی پہلے سے خراب ہوتی ہے۔</p>\n<p>کمپریس کرنے سے پہلے منزل کے اصول جانچیں۔ زیادہ سے زیادہ فائل سائز، مطلوبہ ابعاد اور قبول شدہ فارمیٹ نوٹ کریں۔</p>\n<p>طے کریں کہ تصویر کس لیے ہے۔ مصنوعات کی تصویر کو تیز تفصیل چاہیے، جبکہ بلاگ تھمب نیل میں تھوڑی نرمی چل جاتی ہے۔</p>\n<h2 id=\"step-1-open\">مرحلہ 1: 200KB ٹول کھولیں</h2>\n<p>براؤزر میں <a href=\"/ur/tasveer-compress-karein-200kb-tak/\">Compress Image to 200KB ٹول</a> کھولیں۔ اکاؤنٹ یا انسٹال کی ضرورت نہیں ہے، اور صفحہ جلد کھلتا ہے۔</p>\n<p>ٹول مکمل طور پر آپ کے آلے پر چلتا ہے۔ آپ کی تصویریں مقامی طور پر پروسیس ہوتی ہیں اور کبھی کسی سرور پر اپ لوڈ نہیں ہوتیں، جو غیر جاری مصنوعات کے لیے اہم ہے۔</p>\n<p>اگر آپ فون پر ہیں تو صفحہ ویسے ہی کام کرتا ہے۔ اپ لوڈ والے حصے پر ٹیپ کریں اور گیلری سے تصویر چنیں۔ اگر آپ اکثر تصویریں کمپریس کرتے ہیں تو صفحہ بک مارک کر لیں۔</p>\n<h2 id=\"step-2-upload\">مرحلہ 2: اپنی تصویر اپ لوڈ کریں</h2>\n<p>فائل کو صفحے پر گھسیٹ دیں یا براؤز کرنے کے لیے ٹیپ کریں۔ JPG، PNG، WebP اور HEIC فائلیں قبول ہوتی ہیں، ہر ایک 25 MB تک۔</p>\n<p>اپنے پاس موجود بہترین کوالٹی والا نسخہ اپ لوڈ کریں۔ 12 میگا پکسل اصل کمپریسر کو چھوٹی کاپی سے کہیں زیادہ مواد دیتا ہے۔</p>\n<p>بیچ کے لیے کئی فائلیں ایک ساتھ چنیں۔ ہر ایک 200KB تک کمپریس ہوتی ہے، اور آپ انہیں ZIP کے طور پر ایک ساتھ ڈاؤن لوڈ کرتے ہیں۔</p>\n<h2 id=\"step-3-format\">مرحلہ 3: آؤٹ پٹ فارمیٹ چنیں</h2>\n<p>تصویروں کے لیے JPG محفوظ پہلے سے طے شدہ انتخاب ہے۔ یہ ہر جگہ قبول ہوتا ہے اور 200KB پر بہترین نتائج دیتا ہے۔</p>\n<p>اگر منزل قبول کرتی ہو اور آپ تیز ترین نتیجہ چاہتے ہوں تو WebP چنیں۔ WebP اسی سائز پر کنارے تھوڑے صاف رکھتا ہے۔</p>\n<p>PNG صرف فلیٹ رنگ، تیز لکیروں یا شفافیت والے گرافکس کے لیے رکھیں۔ PNG میں محفوظ تصویر 200KB تک پہنچنے میں مشکل کرے گی۔</p>\n<h2 id=\"step-4-run\">مرحلہ 4: کمپریشن چلائیں</h2>\n<p>ٹول خودکار بائنری کوالٹی تلاش چلاتا ہے۔ یہ کوالٹی سطحیں آزماتا ہے جب تک وہ سب سے اونچی سطح نہ مل جائے جو 200KB سے نیچے فٹ ہو۔</p>\n<p>آپ کو کوالٹی فیصد چننے کی ضرورت نہیں ہے۔ تلاش آپ کی مخصوص تصویر کے لیے بہترین عدد ڈھونڈتی ہے، جو اکثر گول عدد نہیں ہوتا۔</p>\n<p>Under 200KB والی تصدیق تلاش کریں۔ یہ بیج بتاتا ہے کہ فائل حد پاس کر گئی ہے اور استعمال کے لیے تیار ہے۔ اگر ہدف چھوٹ گیا تو فارمیٹ JPG کریں۔</p>\n<h2 id=\"step-5-preview\">مرحلہ 5: نتیجہ احتیاط سے پیش نظارہ دیکھیں</h2>\n<p>ڈاؤن لوڈ سے پہلے کمپریس شدہ تصویر مکمل سائز میں پیش نظارہ دیکھیں۔ چھوٹا تھمب نیل وہ مسائل چھپاتا ہے جو مکمل سائز پر واضح ہوتے ہیں۔</p>\n<p>پہلے باریک تفصیل جانچیں۔ کپڑے کی بناوٹ، زیور کی چمک اور چھپے لیبل سب سے پہلے نرم ہوتے ہیں۔</p>\n<p>پھر متن جانچیں۔ تصویر میں کوئی بھی لفظ پڑھنے کے قابل رہنا چاہیے، خاص طور پر اسکرین شاٹ، انفوگرافک اور سرٹیفکیٹ میں۔</p>\n<h2 id=\"step-6-download\">مرحلہ 6: ڈاؤن لوڈ کریں اور ترتیب دیں</h2>\n<p>فائل ڈاؤن لوڈ کریں۔ اس کا نام اسے 200KB والا نسخہ ظاہر کرے گا، اس لیے یہ اصل سے الجھے گی نہیں۔</p>\n<p>اپنے آلے پر فائل سائز جانچیں۔ یہ 200KB سے تھوڑا نیچے پڑھنا چاہیے، عام طور پر 198KB سے 199.9KB کے درمیان۔</p>\n<p>کمپریس شدہ کاپی اصل کے ساتھ رکھیں، اس کی جگہ نہیں۔ دونوں رکھنے کا مطلب ہے کہ آپ ہمیشہ مختلف ترتیبات سے دوبارہ آزما سکتے ہیں۔</p>\n<h2 id=\"fixing-problems\">عام مسائل کا حل</h2>\n<p>اگر تصویر دھندلی لگے تو ماخذ پہلے سے بہت چھوٹا ہو سکتا ہے۔ بڑے اصل سے شروع کریں اور دوبارہ کمپریس کریں۔</p>\n<p>اگر ہدف چھوٹ گیا تو JPG پر جائیں اور اسکیلنگ کی اجازت دیں۔ یہ دو تبدیلیاں 200KB پر زیادہ تر ناکامیاں حل کر دیتی ہیں۔</p>\n<p>اگر رنگ غلط لگیں تو جانچیں کہ تصویر کا پس منظر شفاف تو نہیں تھا۔ شفاف PNG کو JPG میں بدلنے سے پس منظر سفید بھر جاتا ہے۔</p>\n<h2 id=\"product-photo-workflow\">ورک فلو: دکان کے لیے مصنوعات کی تصویر</h2>\n<p>سادہ پس منظر پر اچھی روشنی والے اسٹوڈیو شاٹ سے شروع کریں۔ اچھی روشنی اور صاف پس منظر کمپریشن کو کہیں آسان بنا دیتے ہیں۔</p>\n<p>اصل کو 200KB ٹول پر اپ لوڈ کریں اور فارمیٹ JPG رکھیں۔ زیادہ تر دکانیں اور مارکیٹ پلیس قبول شدہ فارمیٹ میں JPG کو پہلے لکھتی ہیں۔</p>\n<p>مصنوعات کو قریب سے پیش نظارہ دیکھیں۔ ڈاؤن لوڈ سے پہلے مکمل سائز میں کپڑے کی بناوٹ، چھپے لیبل اور کنارے جانچیں۔</p>\n<h2 id=\"blog-workflow\">ورک فلو: بلاگ کی نمایاں تصویریں</h2>\n<p>کئی پوسٹوں کی نمایاں تصویریں جمع کریں اور انہیں ایک بیچ کے طور پر اپ لوڈ کریں۔ ہر ایک 200KB تک کمپریس ہوتی ہے۔</p>\n<p>اگر آپ کا پلیٹفارم سپورٹ کرتا ہو تو بلاگ کے لیے WebP استعمال کریں۔ درجنوں تصویروں پر چھوٹی کوالٹی بہتری جمع ہو جاتی ہے۔</p>\n<p>بیچ کے تین یا چار نتائج پیش نظارہ دیکھیں، صرف پہلا نہیں۔ اچھے نتائج میں ایک خراب نتیجہ چھپ سکتا ہے۔</p>\n<h2 id=\"phone-workflow\">ورک فلو: اپنے فون پر</h2>\n<p>موبائل براؤزر میں ٹول کھولیں اور اپ لوڈ والے حصے پر ٹیپ کریں۔ گیلری سے اصل تصویر چنیں۔</p>\n<p>آئی فون کی تصویریں HEIC فائلیں ہو سکتی ہیں۔ انہیں سیدھا اپ لوڈ کریں، ٹول کمپریشن کے دوران تبدیلی سنبھال لیتا ہے۔</p>\n<p>نتیجہ فون کی اسکرین پر پیش نظارہ دیکھیں، پھر زوم کرنے کے لیے چٹکی بھر کر دیکھیں۔ ڈاؤن لوڈ سے پہلے باریک تفصیل اور کوئی بھی متن جانچیں۔</p>\n<h2 id=\"checking-dimensions\">کمپریشن کے بعد ابعاد جانچنا</h2>\n<p>فائل سائز صرف آدھی کہانی ہے۔ کچھ منزلیں پکسل ابعاد بھی جانچتی ہیں، اور غلط سائز والی 200KB فائل پھر بھی ناکام ہوتی ہے۔</p>\n<p>ڈاؤن لوڈ شدہ فائل کی خصوصیات کھول کر پکسل گنتی پڑھیں۔ اپ لوڈ سے پہلے اسے منزل کے اصولوں سے ملائیں۔</p>\n<p>اگر ٹول نے تصویر چھوٹی کر دی تو ابعاد اصل سے چھوٹے ہوں گے۔ یہ معمول ہے جب صرف کوالٹی سے 200KB تک نہیں پہنچا جا سکا۔</p>\n<h2 id=\"infographics-200kb\">200KB پر انفوگرافک اور چارٹ</h2>\n<p>انفوگرافک مشکل تصویریں ہوتی ہیں۔ ان میں متن، باریک لکیریں اور فلیٹ رنگ ملے ہوتے ہیں، اور ہر جز کو تیز رہنے کے لیے ڈیٹا چاہیے ہوتا ہے۔</p>\n<p>200KB پر زیادہ تر انفوگرافک پڑھنے کے قابل رہتے ہیں۔ چھوٹے لیبل جو 100KB پر دھندلے ہوتے ہیں، اس سائز پر صاف رہتے ہیں۔</p>\n<p>PNG انفوگرافک کے لیے دلکش ہے کیونکہ یہ لکیریں بالکل رکھتا ہے۔ مگر تفصیلی انفوگرافک PNG میں 200KB تک پہنچنے کے لیے ابعاد میں بھاری کٹوتی مانگ سکتا ہے۔</p>\n<h2 id=\"social-sharing\">سوشل شیئرنگ اور 200KB تصویریں</h2>\n<p>سوشل پلیٹفارم آپ کی اپ لوڈ دوبارہ کمپریس کرتے ہیں، اس لیے 200KB سے شروع کرنا انہیں کام کرنے کے لیے صاف فائل دیتا ہے۔ بڑا اصل اکثر بدتر دکھائی دے کر واپس آتا ہے۔</p>\n<p>پروفائل اور کور تصویروں کو سب سے زیادہ فائدہ ہوتا ہے۔ 200KB تصویر فوراً اپ لوڈ ہوتی ہے اور پلیٹفارم کی اپنی کمپریشن میں تفصیل برقرار رکھتی ہے۔</p>\n<p>متن والے اوورلے والی پوسٹوں کے لیے متن قریب سے پیش نظارہ دیکھیں۔ پلیٹفارم کمپریشن چھوٹے حروف نرم کر دیتی ہے، اس لیے تیز ترین 200KB فائل سے شروع کریں۔</p>\n<h2 id=\"print-vs-web\">پرنٹ بمقابلہ ویب: کون سا چاہیے، یہ جاننا</h2>\n<p>200KB تصویر ویب تصویر ہے۔ یہ اسکرین پر بہترین اور کاغذ پر خراب دکھائی دیتی ہے، اور دونوں کو الجھانے سے مایوسی ہوتی ہے۔</p>\n<p>پرنٹ کو تقریباً 300 پکسل فی انچ چاہییں۔ 200KB فائل میں چھوٹے پرنٹ سے بڑے کسی بھی چیز کے لیے شاذ ہی کافی پکسل ہوتے ہیں۔</p>\n<p>اگر کلائنٹ پرنٹ فائل مانگے تو اصل بھیجیں۔ 200KB کاپی ویب سائٹ کے لیے ہے، اور اصل پرنٹر کے لیے ہے۔</p>\n<h2 id=\"team-standards\">اپنی ٹیم کے لیے 200KB معیار طے کرنا</h2>\n<p>ساتھ شائع کرنے والی ٹیموں کو مشترکہ معیار چاہیے ہوتا ہے۔ فی تصویر 200KB پر اتفاق کرنے سے ہر مصنف الگ اندازہ لگانا بند کر دیتا ہے۔</p>\n<p>معیار لکھ لیں: فارمیٹ، سائز اور نام۔ ٹیم وکی میں ایک صفحے کی رہنما سو چھوٹے سوالات روک دیتی ہے۔</p>\n<p>نئے آنے والوں کے ساتھ ٹول کا لنک شیئر کریں۔ 200KB کمپریسر کا بک مارک کمپریشن نظریہ کی لمبی وضاحت سے زیادہ مفید ہے۔</p>\n<h2 id=\"troubleshooting-checklist\">خرابی دور کرنے کی چیک لسٹ</h2>\n<p>جب کچھ غلط ہو تو چیک لسٹ ترتیب سے دیکھیں۔ زیادہ تر مسائل کی وجہ سادہ ہوتی ہے اور حل بھی سادہ ہوتا ہے۔</p>\n<p>پہلے ماخذ فائل جانچیں۔ چھوٹی یا خراب اصل کسی بھی ترتیب سے اچھا 200KB نتیجہ نہیں دے سکتی۔</p>\n<p>دوسرے، فارمیٹ جانچیں۔ PNG تصویریں اور شفاف تصویریں 200KB پر ہدف چھوٹنے کی سب سے عام وجہ ہیں۔</p>\n<h2 id=\"final-check-200kb\">اپ لوڈ سے پہلے آخری جانچ</h2>\n<p>تیار تصویر مکمل سائز میں ایک آخری بار کھولیں۔ لائیو ہونے سے پہلے تفصیل، متن اور رنگ جانچیں۔</p>\n<p>یقین کریں کہ فائل سائز آپ کے آلے پر 200KB سے تھوڑا نیچے پڑھتا ہے۔ 198KB سے 199.9KB کے درمیان عدد بالکل درست ہے۔</p>\n<p>200KB اتنا اچھا کیوں کام کرتا ہے، اس کا پس منظر <a href=\"/ur/blog/tasveer-200kb-tak-compress-karein-rehnumai/\">Compress Image to 200KB: Complete Guide</a> میں پڑھیں۔ پورٹل کی مخصوص ترتیبات کے لیے <a href=\"/ur/blog/200kb-tasveer-job-portal-settings/\">200KB Images for Job Portals and Forms</a> دیکھیں۔ اگر بڑی فائل چاہیے تو <a href=\"/ur/tasveer-compress-karein-500kb-tak/\">500KB کمپریسر</a> اور بھی زیادہ تفصیل رکھتا ہے۔</p>\n";

